const FIELDS = ['storeCode', 'storeName', 'vendorName', 'vendorEmail', 'vendorPhone'];

function toRows(rows, serviceType) {
  return rows.map(r => {
    const o = { id: serviceType + '|' + r[0], serviceType };
    FIELDS.forEach((k, i) => { o[k] = r[i]; });
    return o;
  });
}

export const AMC_VENDOR_ROWS = [
  ...toRows(AC_ROWS, 'AC AMC'),
  ...toRows(LIFT_ROWS, 'Lift AMC'),
  ...toRows(PEST_ROWS, 'Pest Control AMC'),
];
